// NewConfirmPayload builds a oktaResourceConnections service confirm endpoint
// payload.
func NewConfirmPayload(body *ConfirmRequestBody, sessionToken *string) *oktaresourceconnections.ConfirmPayload {
	v := &oktaresourceconnections.ConfirmPayload{}
	v.Connections = make([]*oktaresourceconnections.OktaResourceConnectionConfirmation, len(body.Connections))
	for i, val := range body.Connections {
		if val == nil {
			v.Connections[i] = nil
			continue
		}
		v.Connections[i] = unmarshalOktaResourceConnectionConfirmationRequestBodyToOktaresourceconnectionsOktaResourceConnectionConfirmation(val)
	}
	v.SessionToken = sessionToken

	return v
}

